/**
 * Represents error responses based on the "Problem Details for HTTP APIs" specification (RFC 7807).
 * Provides a standardized format for communicating machine-readable details of errors in HTTP APIs.
 */
export interface ProblemDetail {
  /** A URI reference that identifies the problem type. */
  type?: string;
  /** A short, human-readable summary of the problem type. */
  title: string;
  /** The HTTP status code generated by the origin server for this occurrence of the problem. */
  status: number;
  /** A human-readable explanation specific to this occurrence of the problem. */
  detail: string;
  /** A URI reference that identifies the specific occurrence of the problem. */
  instance: string;
  /**
   * Optional map of field-specific errors, where keys are property names and values are arrays of error messages.
   * @example { "email": ["Email is invalid"], "password": ["Password is too short"] }
   */
  errors?: Record<string, string[]>;
}


/**
 * Wrapper for error responses where the backend nests the error information
 * within a dedicated details field.
 */
export type ApiProblemDetail = {
  /**
   * The standardized problem details conforming to RFC 7807.
   * @see {@link ProblemDetail}
   */
  details: ProblemDetail;
}